{"command": "python3 -c "
import re
files=[]
cur=None
counts={}
for line in open('/tmp/diff.txt'):
    m=re.match(r'diff --git a/(\S+) b/',line)
    if m:
        cur=m.group(1)
        counts[cur]=0
        continue
    if line.startswith('+') and not line.startswith('+++'):
        counts[cur]+=1
    elif line.startswith('-') and not line.startswith('---'):
        counts[cur]+=1
for k,v in sorted(counts.items(), key=lambda x:-x[1]):
    print(k,v)
